head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#f7f6ee" value="#f7f6ee"/><Variable name="page.text" description="Text color" type="color" default="#223d31" value="#223d31"/><Variable name="theme.accent" description="Accent color" type="color" default="#355f48" value="#355f48"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:"Libre Baskerville",Georgia,serif;--body:"Source Sans 3",sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
html{scroll-behavior:smooth}body{margin:0}a{color:inherit}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:5px}img{max-width:100%}header,footer{position:relative}nav{display:flex;gap:24px;flex-wrap:wrap}nav a{text-decoration:none}.wordmark{text-decoration:none;font-weight:700}.brandline{display:flex;align-items:center;justify-content:space-between;gap:24px}.eyebrow{font-size:12px;letter-spacing:.16em;text-transform:uppercase}.art{display:block;width:100%;height:auto}p{line-height:1.7}.post-title a{text-decoration:none}.post-meta{font-size:11px;letter-spacing:.07em;text-transform:uppercase}.post-excerpt{line-height:1.6}.post-media{display:block;width:100%;aspect-ratio:16/10;object-fit:cover}.section-heading{font-size:30px;margin:0 0 30px}.post-title{font-size:24px;line-height:1.2}.post-card{min-width:0}footer{margin-top:80px}footer p{margin:0}.footerline{display:flex;justify-content:space-between;gap:25px;align-items:center}.page-content,.post-body{max-width:760px;margin:auto}.post-body{line-height:1.8}main>.section-heading,main>.posts-grid{max-width:1200px;margin-left:auto;margin-right:auto}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.brandline,.footerline{align-items:flex-start;flex-direction:column}nav{gap:16px}.section-heading{font-size:26px}.post-title{font-size:22px}main>.section-heading,main>.posts-grid{margin-left:20px;margin-right:20px}}body{background:#f7f6ee;color:#223d31;font:16px "Source Sans 3",sans-serif}header{padding:30px 6vw;border-top:7px solid #223d31;border-bottom:1px solid #bcc7b6}.wordmark{font:700 27px "Libre Baskerville",serif;letter-spacing:-.055em}.wordmark span{font:8px "Source Sans 3",sans-serif;display:block;letter-spacing:.24em;margin-top:8px}nav{font-size:13px}.cents-hero{display:grid;grid-template-columns:1.2fr 1fr;padding:65px 6vw;align-items:center;gap:50px}.eyebrow{font-size:10px;letter-spacing:.15em;color:#536e56;font-weight:600}.cents-hero h1{font:400 clamp(42px,4.5vw,64px)/1.15 "Libre Baskerville",serif;letter-spacing:-.04em;margin:25px 0}.cents-hero h1 em{color:#527259}.cents-hero>div>p:not(.eyebrow){max-width:380px;font-size:15px;color:#56694f}.cents-button{display:inline-flex;gap:35px;background:#355f48;color:#fff;padding:16px 20px;text-decoration:none;font-size:13px;margin-top:14px;border-radius:3px}.cents-button span{transition:transform .2s}.cents-button:hover span{transform:translateX(4px)}.ledger-art{background:#e6eadb;border-radius:50% 50% 3px 3px;padding:35px 5px 20px}.ledger-caption{text-align:center;font-size:8px;letter-spacing:.13em;color:#52654e}.learning-paths{padding:55px 6vw;background:#e9ecdf;border-top:1px solid #b9c5ae;border-bottom:1px solid #b9c5ae}.path-heading{text-align:center;max-width:700px;margin:auto}.path-heading h2{font:400 28px/1.4 "Libre Baskerville",serif}.path-heading p:last-child{font-size:14px;color:#56694f}.path-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:35px}.path-grid>a{display:block;text-decoration:none;background:#f9faf2;border:1px solid #b9c5ae;border-radius:3px;padding:28px;transition:transform .2s}.path-grid>a:hover{transform:translateY(-4px)}.path-grid span{font-size:9px;letter-spacing:.12em;color:#536e56}.path-grid h3{font:400 21px "Libre Baskerville",serif;margin:25px 0 15px}.path-grid p{font-size:13px;color:#56694f}.path-grid b{display:block;margin-top:25px;font-size:11px;font-weight:600}.cents-journal{margin:65px 6vw 12px}.section-heading{font:400 33px "Libre Baskerville",serif;margin:0 6vw 30px}.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:35px;margin:0 6vw}.post-card{border-top:2px solid #355f48;padding-top:18px}.post-media{display:none}.post-meta{font-size:10px;color:#536e56}.post-title{font:400 24px/1.35 "Libre Baskerville",serif;margin:20px 0 15px}.post-excerpt{font-size:14px;color:#56694f}.cents-glossary{display:grid;grid-template-columns:1fr 1.15fr;gap:65px;margin:75px 6vw 0;padding:45px 0;border-top:1px solid #aebda6}.cents-glossary h2{font:400 37px/1.3 "Libre Baskerville",serif;letter-spacing:-.035em}.cents-glossary p{font-size:14px;color:#56694f}.cents-glossary details{border-bottom:1px solid #b4c0aa;padding:21px 0}.cents-glossary summary{cursor:pointer;display:flex;justify-content:space-between;font:18px "Libre Baskerville",serif}.cents-glossary summary span{font:22px "Source Sans 3",sans-serif}.cents-glossary details[open] summary span{transform:rotate(45deg)}.cents-note{margin:10px 6vw 40px;padding:22px 30px;background:#e9ecdf;border-left:3px solid #7e8d6c}.cents-note strong{font-size:9px;letter-spacing:.12em}.cents-note p{font-size:12px;color:#56694f;margin-bottom:0}footer{padding:40px 6vw;border-top:1px solid #b9c5ae;margin-top:35px;font-size:11px}.cents-brand{font:22px "Libre Baskerville",serif}@media(max-width:700px){.cents-hero{grid-template-columns:1fr;gap:35px;padding-top:40px}.cents-hero h1{font-size:43px}.ledger-art{max-width:460px}.path-grid,.posts-grid,.cents-glossary{grid-template-columns:1fr}.cents-glossary{gap:15px}.path-heading h2{font-size:25px}.section-heading{font-size:27px}}
.latest{max-width:none;margin:55px 0;padding:0}.latest>.section-heading,.latest>.posts-grid{max-width:none}a:hover span,a:focus-visible span{transition:transform .2s}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{animation:none!important;transition:none!important}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
